#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

/* Forward declare libwebp decode function */
uint8_t *WebPDecodeRGBA(const uint8_t *data, size_t data_size, int *width, int *height);

int main() {
    FILE *f = fopen("assets/pixel.webp", "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *data = malloc(len);
    fread(data, 1, len, f);
    fclose(f);

    int w = 0, h = 0;
    uint8_t *rgba = WebPDecodeRGBA(data, len, &w, &h);
    if (rgba) {
        printf("WebP decoded successfully: %dx%d, first pixel: R=%d G=%d B=%d A=%d\n",
               w, h, rgba[0], rgba[1], rgba[2], rgba[3]);
        free(rgba);
    } else {
        printf("WebP decode failed\n");
    }
    free(data);
    return 0;
}
