{"command":"cat << 'EOF' > /tmp/test_png.c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

/* Forward declare libpng functions */
void *png_create_read_struct(const char *user_png_ver, void *error_ptr, void *error_fn, void *warn_fn);
void *png_create_info_struct(void *png_ptr);
void png_init_io(void *png_ptr, FILE *fp);
void png_read_info(void *png_ptr, void *info_ptr);
uint32_t png_get_image_width(void *png_ptr, void *info_ptr);
uint32_t png_get_image_height(void *png_ptr, void *info_ptr);
uint8_t png_get_color_type(void *png_ptr, void *info_ptr);
uint8_t png_get_bit_depth(void *png_ptr, void *info_ptr);
void png_set_expand(void *png_ptr);
void png_set_strip_16(void *png_ptr);
void png_set_gray_to_rgb(void *png_ptr);
void png_set_add_alpha(void *png_ptr, uint32_t filler, int location);
void png_read_update_info(void *png_ptr, void *info_ptr);
void png_read_image(void *png_ptr, uint8_t **row_pointers);
void png_destroy_read_struct(void **png_ptr_ptr, void **info_ptr_ptr, void **end_info_ptr_ptr);

int main() {
    FILE *f = fopen("assets/pixel.png", "rb");
    if (!f) return 1;
    void *png = png_create_read_struct("1.6.37", NULL, NULL, NULL);
    void *info = png_create_info_struct(png);
    png_init_io(png, f);
    png_read_info(png, info);

    uint32_t w = png_get_image_width(png, info);
    uint32_t h = png_get_image_height(png, info);
    uint8_t color_type = png_get_color_type(png, info);
    uint8_t bit_depth = png_get_bit_depth(png, info);

    if (bit_depth == 16) png_set_strip_16(png);
    png_set_expand(png);
    png_set_gray_to_rgb(png);
    png_set_add_alpha(png, 0xFF, 1 /* PNG_FILLER_AFTER */);
    png_read_update_info(png, info);

    uint8_t *img = malloc(w * h * 4);
    uint8_t **rows = malloc(h * sizeof(uint8_t*));
    for (uint32_t y = 0; y < h; y++) rows[y] = img + y * w * 4;
    png_read_image(png, rows);

    printf("PNG decoded successfully: %dx%d, first pixel: R=%d G=%d B=%d A=%d\n",
           w, h, img[0], img[1], img[2], img[3]);

    free(rows); free(img); fclose(f);
    return 0;
}
