import sys, os, re

class OptionError(Exception):
    def __init__(self, message):
        self.message = message

def parse_bool_val(opt_name, val, allow_auto=False):
    v = val.lower()
    if v in ("on", "1", "true", "yes"):
        return True
    if v in ("off", "0", "false", "no"):
        return False
    if allow_auto and v == "auto":
        return "auto"

    msg_map = {
        "animate": "Animate mode must be one of [on, off].",
        "label": "Label mode must be one of [on, off].",
        "link": "Link mode must be one of [auto, on, off].",
        "relative": "Relative positioning must be one of [on, off].",
        "polite": "Polite mode must be one of [on, off].",
        "preprocess": "Preprocessing must be one of [on, off].",
        "exact-size": "Exact size selector must be one of [on, off, auto].",
    }
    if opt_name in msg_map:
        raise OptionError(msg_map[opt_name])
    raise OptionError(f"Value '{val}' for --{opt_name} must be on or off.")

def parse_size_val(opt_name, val):
    # e.g. 80x25, 80x, x25
    m = re.match(r'^(\d+)?x(\d+)?$', val, re.IGNORECASE)
    if not m or (m.group(1) is None and m.group(2) is None):
        if opt_name == "size":
            raise OptionError("Size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25.")
        elif opt_name == "view-size":
            raise OptionError("View size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25.")
        else:
            raise OptionError(f"Invalid size '{val}'.")
    w = int(m.group(1)) if m.group(1) else None
    h = int(m.group(2)) if m.group(2) else None
    return w, h

def parse_grid_val(val):
    if val.lower() == "auto":
        return "auto", "auto"
    m = re.match(r'^(\d+)?x?(\d+)?$', val, re.IGNORECASE)
    if not m or (m.group(1) is None and m.group(2) is None):
        raise OptionError("Grid size must be specified as [cols]x[rows], e.g. 2x2. Either cols or rows may be omitted.")
    c = int(m.group(1)) if m.group(1) else None
    r = int(m.group(2)) if m.group(2) else None
    return c, r

class Config:
    def __init__(self):
        self.files = []
        self.files0_path = None
        self.files_path = None
        self.verbose = False
        self.format = "symbols"
        self.optimize = 5
        self.colors = "16" # default guessed, or full/256/16 depending on tty
        self.colors_explicit = False
        self.size_w = None
        self.size_h = None
        self.view_w = None
        self.view_h = None
        self.scale = None
        self.stretch = False
        self.fit_width = False
        self.font_ratio = 0.5
        self.margin_bottom = 1
        self.margin_right = 0
        self.align = "top,left"
        self.clear = False
        self.grid = None
        self.label = False
        self.link = "auto"
        self.animate = True
        self.duration = None
        self.speed = 1.0
        self.watch = False
        self.bg = None
        self.fg = None
        self.invert = False
        self.threshold = 0.5
        self.preprocess = None
        self.color_space = "rgb"
        self.color_extractor = "average"
        self.dither = None
        self.dither_grain_w = 4
        self.dither_grain_h = 4
        self.dither_intensity = 1.0
        self.symbols = None
        self.fill = None
        self.fg_only = False
        self.relative = False
        self.polite = False
        self.passthrough = "auto"
        self.exact_size = "auto"
        self.probe = 5.0
        self.probe_mode = "any"
        self.threads = -1
        self.work = 5

def parse_args(argv):
    prog_name = argv[0] if argv else "./executable"
    cfg = Config()

    # Check stdout tty
    is_tty = sys.stdout.isatty()
    if not is_tty:
        cfg.colors = "none"

    i = 1
    n = len(argv)

    while i < n:
        arg = argv[i]

        if arg == "--":
            i += 1
            while i < n:
                cfg.files.append(argv[i])
                i += 1
            break

        if arg.startswith("--"):
            if "=" in arg:
                opt, val = arg.split("=", 1)
            else:
                opt = arg
                val = None

            opt_name = opt[2:]

            if opt_name == "help":
                return "help", None
            elif opt_name == "version":
                return "version", None
            elif opt_name == "verbose":
                cfg.verbose = True
            elif opt_name == "format":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --format")
                if val not in ("iterm", "kitty", "sixels", "symbols"):
                    raise OptionError(f"Output format given as '{val}'. Must be one of [iterm, kitty, sixels, symbols].")
                cfg.format = val
            elif opt_name == "colors":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --colors")
                if val not in ("none", "2", "8", "16/8", "16", "240", "256", "full"):
                    raise OptionError("Colors must be one of [none, 2, 8, 16/8, 16, 240, 256, full].")
                cfg.colors = val
                cfg.colors_explicit = True
            elif opt_name == "size":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --size")
                cfg.size_w, cfg.size_h = parse_size_val("size", val)
            elif opt_name == "view-size":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --view-size")
                cfg.view_w, cfg.view_h = parse_size_val("view-size", val)
            elif opt_name == "scale":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --scale")
                if val.lower() == "max":
                    cfg.scale = "max"
                else:
                    try:
                        cfg.scale = float(val)
                        if cfg.scale <= 0: raise ValueError()
                    except ValueError:
                        raise OptionError("Scale must be specified as a positive real number or fraction.")
            elif opt_name == "stretch":
                cfg.stretch = True
                cfg.scale = "max"
            elif opt_name == "fit-width":
                cfg.fit_width = True
            elif opt_name == "font-ratio":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --font-ratio")
                try:
                    if "/" in val:
                        num, den = val.split("/", 1)
                        cfg.font_ratio = float(num) / float(den)
                    else:
                        cfg.font_ratio = float(val)
                    if cfg.font_ratio <= 0: raise ValueError()
                except ValueError:
                    raise OptionError("Font ratio must be specified as a positive real number or fraction.")
            elif opt_name == "animate":
                if val is None:
                    if i + 1 < n and argv[i+1].lower() in ("on", "off"):
                        i += 1; val = argv[i]
                    else:
                        val = "on"
                cfg.animate = parse_bool_val("animate", val)
            elif opt_name == "duration":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --duration")
                if val.lower() in ("inf", "infinite"):
                    cfg.duration = float("inf")
                else:
                    try:
                        cfg.duration = float(val)
                        if cfg.duration < 0: raise ValueError()
                    except ValueError:
                        raise OptionError("Duration must be a positive real number or fraction, \"inf\" or \"infinite\".")
            elif opt_name == "label":
                if val is None:
                    if i + 1 < n and argv[i+1].lower() in ("on", "off"):
                        i += 1; val = argv[i]
                    else:
                        val = "on"
                cfg.label = parse_bool_val("label", val)
            elif opt_name == "grid":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --grid")
                cfg.grid = parse_grid_val(val)
            elif opt_name == "clear":
                cfg.clear = True
            elif opt_name == "symbols":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --symbols")
                cfg.symbols = val
            elif opt_name == "fill":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --fill")
                cfg.fill = val
            elif opt_name == "fg-only":
                cfg.fg_only = True
            elif opt_name == "bg":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --bg")
                cfg.bg = val
            elif opt_name == "fg":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --fg")
                cfg.fg = val
            elif opt_name == "invert":
                cfg.invert = True
            elif opt_name == "threshold":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --threshold")
                try:
                    cfg.threshold = float(val)
                    if not (0.0 <= cfg.threshold <= 1.0): raise ValueError()
                except ValueError:
                    raise OptionError("Opacity threshold must be a real number or fraction in the range [0.0-1.0].")
            elif opt_name == "color-space":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --color-space")
                if val not in ("rgb", "din99d"):
                    raise OptionError("Color space must be one of [rgb, din99d].")
                cfg.color_space = val
            elif opt_name == "color-extractor":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --color-extractor")
                if val not in ("average", "median"):
                    raise OptionError("Color extractor must be one of [average, median].")
                cfg.color_extractor = val
            elif opt_name == "dither":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --dither")
                if val not in ("none", "ordered", "diffusion", "noise"):
