                cfg.dither = val
            elif opt_name == "files":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --files")
                cfg.files_path = val
            elif opt_name == "files0":
                if val is None:
                    i += 1; val = argv[i] if i < n else None
                if not val: raise OptionError("Missing argument for --files0")
                cfg.files0_path = val
