import sys, os, re

class OptionError(Exception):
    def __init__(self, message):
        self.message = message

def parse_bool_val(opt_name, val, allow_auto=False):
    v = val.lower()
    if v in ("on", "1", "true", "yes"):
        return True
    if v in ("off", "0", "false", "no"):
        return False
    if allow_auto and v == "auto":
        return "auto"

    msg_map = {
        "animate": "Animate mode must be one of [on, off].",
        "label": "Label mode must be one of [on, off].",
        "link": "Link mode must be one of [auto, on, off].",
        "relative": "Relative positioning must be one of [on, off].",
        "polite": "Polite mode must be one of [on, off].",
        "preprocess": "Preprocessing must be one of [on, off].",
        "exact-size": "Exact size selector must be one of [on, off, auto].",
    }
    if opt_name in msg_map:
        raise OptionError(msg_map[opt_name])
    raise OptionError(f"Value '{val}' for --{opt_name} must be on or off.")

def parse_size_val(opt_name, val):
    # e.g. 80x25, 80x, x25
    m = re.match(r'^(\d+)?x(\d+)?$', val, re.IGNORECASE)
    if not m or (m.group(1) is None and m.group(2) is None):
        if opt_name == "size":
            raise OptionError("Size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25.")
        elif opt_name == "view-size":
            raise OptionError("View size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25.")
        else:
            raise OptionError(f"Invalid size '{val}'.")
    w = int(m.group(1)) if m.group(1) else None
    h = int(m.group(2)) if m.group(2) else None
    return w, h

def parse_grid_val(val):
    if val.lower() == "auto":
        return "auto", "auto"
    m = re.match(r'^(\d+)?x?(\d+)?$', val, re.IGNORECASE)
    if not m or (m.group(1) is None and m.group(2) is None):
        raise OptionError("Grid size must be specified as [cols]x[rows], e.g. 2x2. Either cols or rows may be omitted.")
    c = int(m.group(1)) if m.group(1) else None
    r = int(m.group(2)) if m.group(2) else None
    return c, r

