#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <setjmp.h>

struct my_error_mgr {
    void (*error_exit) (void *cinfo);
    void (*emit_message) (void *cinfo, int msg_level);
    void (*output_message) (void *cinfo);
    void (*format_message) (void *cinfo, char *buffer);
    void (*reset_error_mgr) (void *cinfo);
    int msg_code;
    char msg_parm[80];
    int trace_level;
    long num_warnings;
    const char **jpeg_message_table;
    int last_jpeg_message;
    const char * const *addon_message_table;
    int first_addon_message;
    int last_addon_message;
    jmp_buf setjmp_buffer;
};

void *jpeg_std_error(struct my_error_mgr *jerr);
void jpeg_CreateDecompress(void *cinfo, int version, size_t structsize);
void jpeg_mem_src(void *cinfo, const uint8_t *inbuffer, unsigned long insize);
int jpeg_read_header(void *cinfo, int require_image);
int jpeg_start_decompress(void *cinfo);
uint32_t jpeg_read_scanlines(void *cinfo, uint8_t **scanlines, uint32_t max_lines);
int jpeg_finish_decompress(void *cinfo);
void jpeg_destroy_decompress(void *cinfo);

static void my_error_exit(void *cinfo) {
    struct my_error_mgr *myerr = *(struct my_error_mgr**)cinfo;
    longjmp(myerr->setjmp_buffer, 1);
}

uint8_t *decode_jpeg_mem(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    uint8_t cinfo[656];
    memset(cinfo, 0, sizeof(cinfo));
    struct my_error_mgr jerr;
    memset(&jerr, 0, sizeof(jerr));

    jpeg_std_error(&jerr);
    jerr.error_exit = my_error_exit;
    *(void**)cinfo = &jerr;

    if (setjmp(jerr.setjmp_buffer)) {
        jpeg_destroy_decompress(cinfo);
        return NULL;
    }

    jpeg_CreateDecompress(cinfo, 80, 656);
    jpeg_mem_src(cinfo, data, size);
    if (jpeg_read_header(cinfo, 1) != 1) {
        jpeg_destroy_decompress(cinfo);
        return NULL;
    }

    jpeg_start_decompress(cinfo);

    uint32_t w = *(uint32_t*)(cinfo + 160);
    uint32_t h = *(uint32_t*)(cinfo + 164);
    int num_comps = *(int*)(cinfo + 168);

    uint8_t *rgba = malloc(w * h * 4);
    uint8_t *line = malloc(w * num_comps);

    for (uint32_t y = 0; y < h; y++) {
        uint8_t *p = line;
        jpeg_read_scanlines(cinfo, &p, 1);
        for (uint32_t x = 0; x < w; x++) {
            if (num_comps == 3) {
                rgba[(y * w + x) * 4 + 0] = line[x * 3 + 0];
                rgba[(y * w + x) * 4 + 1] = line[x * 3 + 1];
                rgba[(y * w + x) * 4 + 2] = line[x * 3 + 2];
                rgba[(y * w + x) * 4 + 3] = 255;
            } else if (num_comps == 1) {
                uint8_t v = line[x];
                rgba[(y * w + x) * 4 + 0] = v;
                rgba[(y * w + x) * 4 + 1] = v;
                rgba[(y * w + x) * 4 + 2] = v;
                rgba[(y * w + x) * 4 + 3] = 255;
            }
        }
    }

    jpeg_finish_decompress(cinfo);
    jpeg_destroy_decompress(cinfo);
    free(line);

    *out_w = (int)w;
    *out_h = (int)h;
    return rgba;
}

int main() {
    FILE *f = fopen("assets/taxic.jpg", "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END); long len = ftell(f); fseek(f, 0, SEEK_SET);
    uint8_t *data = malloc(len); fread(data, 1, len, f); fclose(f);

    int w = 0, h = 0;
    uint8_t *rgba = decode_jpeg_mem(data, len, &w, &h);
    if (rgba) {
        printf("JPEG decoded successfully: %dx%d, first pixel: R=%d G=%d B=%d A=%d\n",
               w, h, rgba[0], rgba[1], rgba[2], rgba[3]);
        free(rgba);
    } else {
        printf("JPEG decode failed\n");
    }
    free(data);
    return 0;
}
