uint8_t *decode_jpeg_mem(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    uint8_t cinfo[656];
    memset(cinfo, 0, sizeof(cinfo));
    struct my_error_mgr jerr;
    memset(&jerr, 0, sizeof(jerr));

    jpeg_std_error(&jerr);
    jerr.error_exit = my_error_exit;
    *(void**)cinfo = &jerr;

    if (setjmp(jerr.setjmp_buffer)) {
        jpeg_destroy_decompress(cinfo);
        return NULL;
    }

    jpeg_CreateDecompress(cinfo, 80, 656);
    jpeg_mem_src(cinfo, data, size);
    if (jpeg_read_header(cinfo, 1) != 1) {
        jpeg_destroy_decompress(cinfo);
        return NULL;
    }

    jpeg_start_decompress(cinfo);

    uint32_t w = *(uint32_t*)(cinfo + 160);
    uint32_t h = *(uint32_t*)(cinfo + 164);
    int num_comps = *(int*)(cinfo + 168);

    uint8_t *rgba = malloc(w * h * 4);
    uint8_t *line = malloc(w * num_comps);

    for (uint32_t y = 0; y < h; y++) {
        uint8_t *p = line;
        jpeg_read_scanlines(cinfo, &p, 1);
        for (uint32_t x = 0; x < w; x++) {
            if (num_comps == 3) {
                rgba[(y * w + x) * 4 + 0] = line[x * 3 + 0];
                rgba[(y * w + x) * 4 + 1] = line[x * 3 + 1];
                rgba[(y * w + x) * 4 + 2] = line[x * 3 + 2];
                rgba[(y * w + x) * 4 + 3] = 255;
            } else if (num_comps == 1) {
                uint8_t v = line[x];
                rgba[(y * w + x) * 4 + 0] = v;
                rgba[(y * w + x) * 4 + 1] = v;
                rgba[(y * w + x) * 4 + 2] = v;
                rgba[(y * w + x) * 4 + 3] = 255;
            }
        }
    }

    jpeg_finish_decompress(cinfo);
    jpeg_destroy_decompress(cinfo);
    free(line);

    *out_w = (int)w;
    *out_h = (int)h;
    return rgba;
}

