    uint32_t w = (data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7];
    uint32_t h = (data[8] << 24) | (data[9] << 16) | (data[10] << 8) | data[11];
    uint8_t *rgba = malloc(w * h * 4);
    uint8_t index[64][4];
    memset(index, 0, sizeof(index));
    for(int i=0; i<64; i++) index[i][3] = 255;

    uint8_t r=0, g=0, b=0, a=255;
    size_t p = 14;
    int run = 0;
    size_t total = (size_t)w * h;

    for (size_t px = 0; px < total; px++) {
        if (run > 0) {
            run--;
        } else {
            if (p < size) {
                uint8_t b1 = data[p++];
                if (b1 == 0xfe) { // QOI_OP_RGB
                    r = data[p++]; g = data[p++]; b = data[p++];
                } else if (b1 == 0xff) { // QOI_OP_RGBA
                    r = data[p++]; g = data[p++]; b = data[p++]; a = data[p++];
                } else if ((b1 & 0xc0) == 0x00) { // QOI_OP_INDEX
                    int idx = b1 & 0x3f;
                    r = index[idx][0]; g = index[idx][1]; b = index[idx][2]; a = index[idx][3];
                } else if ((b1 & 0xc0) == 0x40) { // QOI_OP_DIFF
                    r += ((b1 >> 4) & 0x03) - 2;
                    g += ((b1 >> 2) & 0x03) - 2;
                    b += (b1 & 0x03) - 2;
                } else if ((b1 & 0xc0) == 0x80) { // QOI_OP_LUMA
                    uint8_t b2 = data[p++];
                    int dg = (b1 & 0x3f) - 32;
                    r += dg + ((b2 >> 4) & 0x0f) - 8;
                    g += dg;
                    b += dg + (b2 & 0x0f) - 8;
                } else if ((b1 & 0xc0) == 0xc0) { // QOI_OP_RUN
                    run = b1 & 0x3f;
                }
                int idx = (r * 3 + g * 5 + b * 7 + a * 11) % 64;
                index[idx][0] = r; index[idx][1] = g; index[idx][2] = b; index[idx][3] = a;
            }
        }
        rgba[px * 4 + 0] = r;
        rgba[px * 4 + 1] = g;
        rgba[px * 4 + 2] = b;
        rgba[px * 4 + 3] = a;
    }
    *out_w = (int)w; *out_h = (int)h;
    return rgba;
