uint8_t *decode_png(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    if (size < 8 || memcmp(data, "\x89PNG\r\n\x1a\n", 8) != 0) return NULL;
    void *png = png_create_read_struct("1.6.37", NULL, NULL, NULL);
    if (!png) return NULL;
    void *info = png_create_info_struct(png);
    if (!info) { png_destroy_read_struct(&png, NULL, NULL); return NULL; }

    MemStream s = { data, size, 0 };
    png_set_read_fn(png, &s, png_mem_read);
    png_read_info(png, info);

    uint32_t w = png_get_image_width(png, info);
    uint32_t h = png_get_image_height(png, info);
    png_set_expand(png);
    png_set_strip_16(png);
    png_set_gray_to_rgb(png);
    png_set_add_alpha(png, 0xFF, 1);
    png_read_update_info(png, info);

    uint8_t *rgba = malloc(w * h * 4);
    uint8_t **rows = malloc(h * sizeof(uint8_t*));
    for (uint32_t y = 0; y < h; y++) rows[y] = rgba + y * w * 4;
    png_read_image(png, rows);
    free(rows);
    png_destroy_read_struct(&png, &info, NULL);
    *out_w = (int)w; *out_h = (int)h;
    return rgba;
}

