    uint8_t *ptr = WebPDecodeRGBA(data, size, out_w, out_h);
    if (!ptr) return NULL;
    uint8_t *rgba = malloc((*out_w) * (*out_h) * 4);
    memcpy(rgba, ptr, (*out_w) * (*out_h) * 4);
    free(ptr);
    return rgba;
}

uint8_t *decode_qoi(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    if (size < 14 || memcmp(data, "qoif", 4) != 0) return NULL;
    uint32_t w = (data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7];
    uint32_t h = (data[8] << 24) | (data[9] << 16) | (data[10] << 8) | data[11];
    uint8_t *rgba = malloc(w * h * 4);
    uint8_t index[64][4];
    memset(index, 0, sizeof(index));
    for(int i=0; i<64; i++) index[i][3] = 255;

    uint8_t r=0, g=0, b=0, a=255;
    size_t p = 14;
    int run = 0;
    size_t total = (size_t)w * h;

    for (size_t px = 0; px < total; px++) {
        if (run > 0) {
            run--;
        } else {
            if (p < size) {
                uint8_t b1 = data[p++];
                if (b1 == 0xfe) { // QOI_OP_RGB
                    r = data[p++]; g = data[p++]; b = data[p++];
                } else if (b1 == 0xff) { // QOI_OP_RGBA
                    r = data[p++]; g = data[p++]; b = data[p++]; a = data[p++];
                } else if ((b1 & 0xc0) == 0x00) { // QOI_OP_INDEX
                    int idx = b1 & 0x3f;
                    r = index[idx][0]; g = index[idx][1]; b = index[idx][2]; a = index[idx][3];
                } else if ((b1 & 0xc0) == 0x40) { // QOI_OP_DIFF
                    r += ((b1 >> 4) & 0x03) - 2;
                    g += ((b1 >> 2) & 0x03) - 2;
                    b += (b1 & 0x03) - 2;
                } else if ((b1 & 0xc0) == 0x80) { // QOI_OP_LUMA
                    uint8_t b2 = data[p++];
                    int dg = (b1 & 0x3f) - 32;
                    r += dg + ((b2 >> 4) & 0x0f) - 8;
                    g += dg;
                    b += dg + (b2 & 0x0f) - 8;
                } else if ((b1 & 0xc0) == 0xc0) { // QOI_OP_RUN
                    run = b1 & 0x3f;
                }
                int idx = (r * 3 + g * 5 + b * 7 + a * 11) % 64;
                index[idx][0] = r; index[idx][1] = g; index[idx][2] = b; index[idx][3] = a;
            }
        }
        rgba[px * 4 + 0] = r;
        rgba[px * 4 + 1] = g;
        rgba[px * 4 + 2] = b;
        rgba[px * 4 + 3] = a;
    }
    *out_w = (int)w; *out_h = (int)h;
    return rgba;
}

uint8_t *decode_xwd(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    if (size < 100) return NULL;
    uint32_t header_size = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];
    uint32_t file_version = (data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7];
    if (file_version != 7 && file_version != 6) return NULL;
    uint32_t w = (data[16] << 24) | (data[17] << 16) | (data[18] << 8) | data[19];
    uint32_t h = (data[20] << 24) | (data[21] << 16) | (data[22] << 8) | data[23];
    uint32_t bpp = (data[44] << 24) | (data[45] << 16) | (data[46] << 8) | data[47];
    uint32_t ncolors = (data[72] << 24) | (data[73] << 16) | (data[74] << 8) | data[75];

    uint8_t *rgba = malloc(w * h * 4);
    size_t cmap_offset = header_size;
    size_t pix_offset = header_size + ncolors * 12; // 12 bytes per XWDColor

    if (bpp == 8 && pix_offset + w * h <= size) {
        // Palette lookup
        for (size_t y = 0; y < h; y++) {
            for (size_t x = 0; x < w; x++) {
                uint8_t idx = data[pix_offset + y * w + x];
                size_t c_pos = cmap_offset + idx * 12;
                uint16_t red = (data[c_pos + 4] << 8) | data[c_pos + 5];
                uint16_t green = (data[c_pos + 6] << 8) | data[c_pos + 7];
                uint16_t blue = (data[c_pos + 8] << 8) | data[c_pos + 9];
                rgba[(y * w + x) * 4 + 0] = red >> 8;
                rgba[(y * w + x) * 4 + 1] = green >> 8;
                rgba[(y * w + x) * 4 + 2] = blue >> 8;
                rgba[(y * w + x) * 4 + 3] = 255;
            }
        }
    } else if (bpp >= 24) {
        for (size_t y = 0; y < h; y++) {
            for (size_t x = 0; x < w; x++) {
                size_t p = pix_offset + (y * w + x) * (bpp / 8);
                rgba[(y * w + x) * 4 + 0] = data[p + 0];
                rgba[(y * w + x) * 4 + 1] = data[p + 1];
                rgba[(y * w + x) * 4 + 2] = data[p + 2];
                rgba[(y * w + x) * 4 + 3] = 255;
            }
        }
    }
    *out_w = (int)w; *out_h = (int)h;
    return rgba;
}
