static void png_mem_read(void *png_ptr, uint8_t *out, size_t length) {
    MemStream *s = (MemStream*)png_get_io_ptr(png_ptr);
    if (s->offset + length <= s->size) {
        memcpy(out, s->data + s->offset, length);
        s->offset += length;
    }
}

uint8_t *decode_png(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    if (size < 8 || memcmp(data, "\x89PNG\r\n\x1a\n", 8) != 0) return NULL;
    void *png = png_create_read_struct("1.6.37", NULL, NULL, NULL);
    if (!png) return NULL;
    void *info = png_create_info_struct(png);
    if (!info) { png_destroy_read_struct(&png, NULL, NULL); return NULL; }

    MemStream s = { data, size, 0 };
    png_set_read_fn(png, &s, png_mem_read);
    png_read_info(png, info);

    uint32_t w = png_get_image_width(png, info);
    uint32_t h = png_get_image_height(png, info);
    png_set_expand(png);
    png_set_strip_16(png);
    png_set_gray_to_rgb(png);
    png_set_add_alpha(png, 0xFF, 1);
    png_read_update_info(png, info);

    uint8_t *rgba = malloc(w * h * 4);
    uint8_t **rows = malloc(h * sizeof(uint8_t*));
    for (uint32_t y = 0; y < h; y++) rows[y] = rgba + y * w * 4;
    png_read_image(png, rows);
    free(rows);
    png_destroy_read_struct(&png, &info, NULL);
    *out_w = (int)w; *out_h = (int)h;
    return rgba;
}

static void dummy_error_exit(void *cinfo) {
    struct jpeg_error_mgr *myerr = *(struct jpeg_error_mgr**)cinfo;
    longjmp(myerr->setjmp_buffer, 1);
}

uint8_t *decode_jpeg(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    uint8_t cinfo[656];
    memset(cinfo, 0, sizeof(cinfo));
    struct jpeg_error_mgr jerr;
    memset(&jerr, 0, sizeof(jerr));
    jpeg_std_error(&jerr);
    jerr.error_exit = dummy_error_exit;
    *(void**)cinfo = &jerr;

    if (setjmp(jerr.setjmp_buffer)) {
        jpeg_destroy_decompress(cinfo);
        return NULL;
    }

    jpeg_CreateDecompress(cinfo, 80, 656);
    jpeg_mem_src(cinfo, data, size);
    if (jpeg_read_header(cinfo, 1) != 1) {
        jpeg_destroy_decompress(cinfo);
        return NULL;
    }

    jpeg_start_decompress(cinfo);

    uint32_t w = *(uint32_t*)(cinfo + 136);
    uint32_t h = *(uint32_t*)(cinfo + 140);
    int num_comps = *(int*)(cinfo + 144);

    uint8_t *rgba = malloc(w * h * 4);
    uint8_t *line = malloc(w * (num_comps > 0 ? num_comps : 3));

    for (uint32_t y = 0; y < h; y++) {
        uint8_t *p = line;
        jpeg_read_scanlines(cinfo, &p, 1);
        for (uint32_t x = 0; x < w; x++) {
            if (num_comps == 3) {
                rgba[(y * w + x) * 4 + 0] = line[x * 3 + 0];
                rgba[(y * w + x) * 4 + 1] = line[x * 3 + 1];
                rgba[(y * w + x) * 4 + 2] = line[x * 3 + 2];
                rgba[(y * w + x) * 4 + 3] = 255;
            } else {
                uint8_t v = line[x];
                rgba[(y * w + x) * 4 + 0] = v;
                rgba[(y * w + x) * 4 + 1] = v;
                rgba[(y * w + x) * 4 + 2] = v;
                rgba[(y * w + x) * 4 + 3] = 255;
            }
        }
    }

    jpeg_finish_decompress(cinfo);
    jpeg_destroy_decompress(cinfo);
    free(line);

    *out_w = (int)w; *out_h = (int)h;
    return rgba;
}

uint8_t *decode_webp(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    uint8_t *ptr = WebPDecodeRGBA(data, size, out_w, out_h);
    if (!ptr) return NULL;
    uint8_t *rgba = malloc((*out_w) * (*out_h) * 4);
    memcpy(rgba, ptr, (*out_w) * (*out_h) * 4);
    free(ptr);
    return rgba;
}

uint8_t *decode_tiff_file(const char *filename, int *out_w, int *out_h) {
    void *tif = TIFFOpen(filename, "r");
    if (!tif) return NULL;
    uint32_t w = 0, h = 0;
    TIFFGetField(tif, 256, &w);
    TIFFGetField(tif, 257, &h);
    if (w == 0 || h == 0) { TIFFClose(tif); return NULL; }

    uint32_t *raster = malloc(w * h * 4);
    if (!TIFFReadRGBAImageOriented(tif, w, h, raster, 1, 0)) {
        free(raster); TIFFClose(tif); return NULL;
    }
    TIFFClose(tif);

    // Swap ABGR to RGBA in place
    uint8_t *rgba = (uint8_t*)raster;
    for (uint32_t i = 0; i < w * h; i++) {
        uint8_t r = rgba[i * 4 + 0];
        uint8_t b = rgba[i * 4 + 2];
        rgba[i * 4 + 0] = r;
        rgba[i * 4 + 2] = b;
    }
    *out_w = (int)w; *out_h = (int)h;
    return rgba;
}

uint8_t *decode_svg(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    rsvg_init();
    void *handle = rsvg_handle_new_from_data(data, size, NULL);
    if (!handle) return NULL;
    RsvgDimensionData dim;
    rsvg_handle_get_dimensions(handle, &dim);
    int w = dim.width > 0 ? dim.width : 512;
    int h = dim.height > 0 ? dim.height : 512;

    void *surface = cairo_image_surface_create(0, w, h);
    void *cr = cairo_create(surface);
    rsvg_handle_render_cairo(handle, cr);
    cairo_surface_flush(surface);
    uint8_t *cdata = cairo_image_surface_get_data(surface);

    uint8_t *rgba = malloc(w * h * 4);
    for (int i = 0; i < w * h; i++) {
        uint32_t px = ((uint32_t*)cdata)[i];
        uint8_t a = (px >> 24) & 0xFF;
        uint8_t r = (px >> 16) & 0xFF;
        uint8_t g = (px >> 8) & 0xFF;
        uint8_t b = px & 0xFF;
        if (a > 0 && a < 255) {
            r = (uint8_t)((uint32_t)r * 255 / a);
            g = (uint8_t)((uint32_t)g * 255 / a);
            b = (uint8_t)((uint32_t)b * 255 / a);
        }
        rgba[i * 4 + 0] = r;
        rgba[i * 4 + 1] = g;
        rgba[i * 4 + 2] = b;
        rgba[i * 4 + 3] = a;
    }
    cairo_destroy(cr);
    cairo_surface_destroy(surface);
    g_object_unref(handle);
    *out_w = w; *out_h = h;
    return rgba;
}

uint8_t *decode_qoi(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    if (size < 14 || memcmp(data, "qoif", 4) != 0) return NULL;
    uint32_t w = (data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7];
    uint32_t h = (data[8] << 24) | (data[9] << 16) | (data[10] << 8) | data[11];
    uint8_t *rgba = malloc(w * h * 4);
    uint8_t index[64][4];
    memset(index, 0, sizeof(index));
    for(int i=0; i<64; i++) index[i][3] = 255;

    uint8_t r=0, g=0, b=0, a=255;
    size_t p = 14;
    int run = 0;
    size_t total = (size_t)w * h;

    for (size_t px = 0; px < total; px++) {
        if (run > 0) {
            run--;
        } else {
            if (p < size) {
                uint8_t b1 = data[p++];
                if (b1 == 0xfe) {
                    r = data[p++]; g = data[p++]; b = data[p++];
                } else if (b1 == 0xff) {
                    r = data[p++]; g = data[p++]; b = data[p++]; a = data[p++];
                } else if ((b1 & 0xc0) == 0x00) {
                    int idx = b1 & 0x3f;
                    r = index[idx][0]; g = index[idx][1]; b = index[idx][2]; a = index[idx][3];
                } else if ((b1 & 0xc0) == 0x40) {
                    r += ((b1 >> 4) & 0x03) - 2;
                    g += ((b1 >> 2) & 0x03) - 2;
                    b += (b1 & 0x03) - 2;
                } else if ((b1 & 0xc0) == 0x80) {
                    uint8_t b2 = data[p++];
                    int dg = (b1 & 0x3f) - 32;
                    r += dg + ((b2 >> 4) & 0x0f) - 8;
                    g += dg;
                    b += dg + (b2 & 0x0f) - 8;
                } else if ((b1 & 0xc0) == 0xc0) {
                    run = b1 & 0x3f;
                }
                int idx = (r * 3 + g * 5 + b * 7 + a * 11) % 64;
                index[idx][0] = r; index[idx][1] = g; index[idx][2] = b; index[idx][3] = a;
            }
        }
        rgba[px * 4 + 0] = r;
        rgba[px * 4 + 1] = g;
        rgba[px * 4 + 2] = b;
        rgba[px * 4 + 3] = a;
    }
    *out_w = (int)w; *out_h = (int)h;
    return rgba;
}

uint8_t *decode_xwd(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    if (size < 100) return NULL;
    uint32_t header_size = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];
    uint32_t file_version = (data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7];
    if (file_version != 7 && file_version != 6) return NULL;
    uint32_t w = (data[16] << 24) | (data[17] << 16) | (data[18] << 8) | data[19];
    uint32_t h = (data[20] << 24) | (data[21] << 16) | (data[22] << 8) | data[23];
    uint32_t bpp = (data[44] << 24) | (data[45] << 16) | (data[46] << 8) | data[47];
    uint32_t ncolors = (data[72] << 24) | (data[73] << 16) | (data[74] << 8) | data[75];

    uint8_t *rgba = malloc(w * h * 4);
    size_t cmap_offset = header_size;
    size_t pix_offset = header_size + ncolors * 12;

    if (bpp == 8 && pix_offset + w * h <= size) {
        for (size_t y = 0; y < h; y++) {
            for (size_t x = 0; x < w; x++) {
                uint8_t idx = data[pix_offset + y * w + x];
                size_t c_pos = cmap_offset + idx * 12;
                uint16_t red = (data[c_pos + 4] << 8) | data[c_pos + 5];
                uint16_t green = (data[c_pos + 6] << 8) | data[c_pos + 7];
                uint16_t blue = (data[c_pos + 8] << 8) | data[c_pos + 9];
                rgba[(y * w + x) * 4 + 0] = red >> 8;
                rgba[(y * w + x) * 4 + 1] = green >> 8;
                rgba[(y * w + x) * 4 + 2] = blue >> 8;
                rgba[(y * w + x) * 4 + 3] = 255;
            }
        }
    } else if (bpp >= 24) {
        for (size_t y = 0; y < h; y++) {
            for (size_t x = 0; x < w; x++) {
                size_t p = pix_offset + (y * w + x) * (bpp / 8);
                rgba[(y * w + x) * 4 + 0] = data[p + 0];
                rgba[(y * w + x) * 4 + 1] = data[p + 1];
                rgba[(y * w + x) * 4 + 2] = data[p + 2];
                rgba[(y * w + x) * 4 + 3] = 255;
            }
        }
    }
    *out_w = (int)w; *out_h = (int)h;
    return rgba;
}
