                int idx = (r * 3 + g * 5 + b * 7 + a * 11) % 64;
                index[idx][0] = r; index[idx][1] = g; index[idx][2] = b; index[idx][3] = a;
            }
        }
        rgba[px * 4 + 0] = r;
        rgba[px * 4 + 1] = g;
        rgba[px * 4 + 2] = b;
        rgba[px * 4 + 3] = a;
    }
    *out_w = (int)w; *out_h = (int)h;
    return rgba;
}

uint8_t *decode_xwd(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    if (size < 100) return NULL;
    uint32_t header_size = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];
    uint32_t file_version = (data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7];
    if (file_version != 7 && file_version != 6) return NULL;
