typedef struct {
    int w, h;
    uint8_t *rgba;
    double delay;
} GifFrameInfo;

typedef struct {
    int w, h;
    int num_frames;
    GifFrameInfo *frames;
} GifAnimInfo;

static uint8_t *decode_gif_lzw(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    if (size < 13 || memcmp(data, "GIF", 3) != 0) return NULL;
    uint16_t w = data[6] | (data[7] << 8);
    uint16_t h = data[8] | (data[9] << 8);
    uint8_t flags = data[10];
    int gct_flag = (flags & 0x80) != 0;
    int gct_size = 1 << ((flags & 0x07) + 1);

    uint8_t palette[256][3];
    memset(palette, 0, sizeof(palette));
    size_t pos = 13;
    if (gct_flag && pos + gct_size * 3 <= size) {
        for (int i = 0; i < gct_size; i++) {
            palette[i][0] = data[pos + i * 3 + 0];
            palette[i][1] = data[pos + i * 3 + 1];
            palette[i][2] = data[pos + i * 3 + 2];
        }
        pos += gct_size * 3;
    }

    uint8_t *rgba = malloc(w * h * 4);
    memset(rgba, 0, w * h * 4);

    int trans_idx = -1;

    while (pos < size) {
        uint8_t b = data[pos++];
        if (b == 0x21) { // Extension
            if (pos >= size) break;
            uint8_t ext_type = data[pos++];
            if (ext_type == 0xF9) { // Graphic Control Extension
                if (pos + 6 <= size) {
                    uint8_t gc_flags = data[pos + 1];
                    if (gc_flags & 0x01) {
                        trans_idx = data[pos + 4];
                    }
                    pos += data[pos] + 2;
                }
            } else {
                while (pos < size && data[pos] != 0) {
                    pos += data[pos] + 1;
                }
                pos++;
            }
        } else if (b == 0x2C) { // Image Descriptor
            if (pos + 9 > size) break;
            uint16_t img_left = data[pos + 0] | (data[pos + 1] << 8);
            uint16_t img_top  = data[pos + 2] | (data[pos + 3] << 8);
            uint16_t img_w    = data[pos + 4] | (data[pos + 5] << 8);
            uint16_t img_h    = data[pos + 6] | (data[pos + 7] << 8);
            uint8_t img_flags = data[pos + 8];
            pos += 9;

            uint8_t local_pal[256][3];
            memcpy(local_pal, palette, sizeof(palette));
            if (img_flags & 0x80) { // Local color table
                int lct_size = 1 << ((img_flags & 0x07) + 1);
                if (pos + lct_size * 3 <= size) {
                    for (int i = 0; i < lct_size; i++) {
                        local_pal[i][0] = data[pos + i * 3 + 0];
                        local_pal[i][1] = data[pos + i * 3 + 1];
                        local_pal[i][2] = data[pos + i * 3 + 2];
                    }
                    pos += lct_size * 3;
                }
            }

            if (pos >= size) break;
            uint8_t min_code_size = data[pos++];
            int clear_code = 1 << min_code_size;
            int end_code = clear_code + 1;

            // LZW Decompress
            int code_size = min_code_size + 1;
            int next_code = end_code + 1;
            int max_code = 1 << code_size;

            int prefix[4096];
            uint8_t suffix[4096];
            for (int i = 0; i < clear_code; i++) {
                prefix[i] = -1;
                suffix[i] = (uint8_t)i;
            }

            int bit_buf = 0;
            int bit_cnt = 0;
            int old_code = -1;

            uint8_t stack[4096];
            int stack_ptr = 0;

            int px = 0;
            int total_px = img_w * img_h;

            while (pos < size && px < total_px) {
                uint8_t block_len = data[pos++];
                if (block_len == 0) break;
                if (pos + block_len > size) break;

                for (int i = 0; i < block_len && px < total_px; i++) {
                    bit_buf |= ((int)data[pos + i]) << bit_cnt;
                    bit_cnt += 8;

                    while (bit_cnt >= code_size && px < total_px) {
                        int code = bit_buf & ((1 << code_size) - 1);
                        bit_buf >>= code_size;
                        bit_cnt -= code_size;

                        if (code == clear_code) {
                            code_size = min_code_size + 1;
                            next_code = end_code + 1;
                            max_code = 1 << code_size;
                            old_code = -1;
                            continue;
                        } else if (code == end_code) {
                            break;
                        }

                        int incode = code;
                        if (code >= next_code) {
                            if (old_code != -1) {
                                stack[stack_ptr++] = (uint8_t)suffix[old_code];
                                code = old_code;
                            }
                        }

                        while (code >= clear_code && code < 4096) {
                            stack[stack_ptr++] = suffix[code];
                            code = prefix[code];
                        }
                        if (code >= 0 && code < 4096) {
                            stack[stack_ptr++] = (uint8_t)code;
                        }

                        if (old_code != -1 && next_code < 4096) {
                            prefix[next_code] = old_code;
                            suffix[next_code] = (uint8_t)code;
                            next_code++;
                            if (next_code >= max_code && code_size < 12) {
                                code_size++;
                                max_code = 1 << code_size;
                            }
                        }
                        old_code = incode;

                        while (stack_ptr > 0 && px < total_px) {
                            uint8_t color_idx = stack[--stack_ptr];
                            int lx = px % img_w;
                            int ly = px / img_w;
                            int gx = img_left + lx;
                            int gy = img_top + ly;

                            if (gx < w && gy < h) {
                                if (color_idx != trans_idx) {
                                    rgba[(gy * w + gx) * 4 + 0] = local_pal[color_idx][0];
                                    rgba[(gy * w + gx) * 4 + 1] = local_pal[color_idx][1];
                                    rgba[(gy * w + gx) * 4 + 2] = local_pal[color_idx][2];
                                    rgba[(gy * w + gx) * 4 + 3] = 255;
                                }
                            }
                            px++;
                        }
                    }
                }
                pos += block_len;
            }
            break; // First frame
        } else if (b == 0x3B) { // GIF Trailer
            break;
        }
    }

    *out_w = w; *out_h = h;
    return rgba;
}

uint8_t *decode_gif(const uint8_t *data, size_t size, int *out_w, int *out_h) {
    return decode_gif_lzw(data, size, out_w, out_h);
}
