import os, sys, ctypes

# Find or load decoders library
so_path = os.path.join(os.path.dirname(__file__), "decoders.so")
lib = ctypes.CDLL(so_path)

for fn_name in ['decode_png', 'decode_jpeg', 'decode_webp', 'decode_qoi', 'decode_xwd', 'decode_svg', 'decode_gif']:
    fn = getattr(lib, fn_name)
    fn.restype = ctypes.POINTER(ctypes.c_uint8)

lib.decode_tiff_file.restype = ctypes.POINTER(ctypes.c_uint8)

class ImageLoadError(Exception):
    pass

class ImageFrame:
    def __init__(self, width, height, rgba_bytes):
        self.width = width
        self.height = height
        self.rgba = rgba_bytes # bytes or bytearray of length width * height * 4

def load_image(filepath_or_bytes, filename=""):
    if isinstance(filepath_or_bytes, str):
        if filepath_or_bytes == "-":
            try:
                data = sys.stdin.buffer.read()
                if not data:
                    raise ImageLoadError("Could not cache input stream")
            except Exception:
                raise ImageLoadError("Could not cache input stream")
        else:
            if not os.path.exists(filepath_or_bytes):
                raise ImageLoadError("No such file or directory")
            try:
                with open(filepath_or_bytes, "rb") as f:
                    data = f.read()
            except Exception as e:
                raise ImageLoadError("Could not cache input stream")
    else:
        data = filepath_or_bytes

    if not data:
        raise ImageLoadError("Could not cache input stream")

    w = ctypes.c_int()
    h = ctypes.c_int()
    ptr = None

    # Check headers
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        ptr = lib.decode_png(data, len(data), ctypes.byref(w), ctypes.byref(h))
    elif data.startswith(b"\xff\xd8\xff"):
        ptr = lib.decode_jpeg(data, len(data), ctypes.byref(w), ctypes.byref(h))
    elif len(data) >= 12 and data.startswith(b"RIFF") and data[8:12] == b"WEBP":
        ptr = lib.decode_webp(data, len(data), ctypes.byref(w), ctypes.byref(h))
    elif data.startswith(b"qoif"):
        ptr = lib.decode_qoi(data, len(data), ctypes.byref(w), ctypes.byref(h))
    elif data.startswith(b"GIF87a") or data.startswith(b"GIF89a"):
        ptr = lib.decode_gif(data, len(data), ctypes.byref(w), ctypes.byref(h))
    elif data.startswith(b"MM\x00\x2a") or data.startswith(b"II\x2a\x00"):
        if isinstance(filepath_or_bytes, str) and os.path.exists(filepath_or_bytes):
            ptr = lib.decode_tiff_file(filepath_or_bytes.encode('utf-8'), ctypes.byref(w), ctypes.byref(h))
    elif b"<svg" in data[:1024].lower() or b"<?xml" in data[:1024].lower():
        ptr = lib.decode_svg(data, len(data), ctypes.byref(w), ctypes.byref(h))
    elif len(data) >= 100 and (data[4:8] == b"\x00\x00\x00\x07" or data[4:8] == b"\x00\x00\x00\x06"):
        ptr = lib.decode_xwd(data, len(data), ctypes.byref(w), ctypes.byref(h))

    # Fallback checks if header check missed
    if not ptr:
        for fn in [lib.decode_png, lib.decode_jpeg, lib.decode_webp, lib.decode_qoi, lib.decode_gif, lib.decode_svg, lib.decode_xwd]:
            ptr = fn(data, len(data), ctypes.byref(w), ctypes.byref(h))
            if ptr:
                break

    if not ptr:
        raise ImageLoadError("Unknown file format")

    length = w.value * h.value * 4
    buf = bytes((ctypes.c_uint8 * length).from_address(ctypes.addressof(ptr.contents)))

    # Free C memory
    libc = ctypes.CDLL(None)
    libc.free(ptr)

    return ImageFrame(w.value, h.value, buf)
EOF"}

