import sys, os, base64, math, struct

def rgb_to_ansi256(r, g, b, min_idx=0):
    if r == g == b:
        if r < 8: idx = 16
        elif r > 248: idx = 231
        else: idx = 232 + round(((r - 8) / 247) * 23)
    else:
        r_idx = round(r / 255 * 5)
        g_idx = round(g / 255 * 5)
        b_idx = round(b / 255 * 5)
        idx = 16 + 36 * r_idx + 6 * g_idx + b_idx
    if idx < min_idx:
        idx = min_idx
    return idx

def rgb_to_ansi16(r, g, b, is_bright=True):
    cols = [
        (0,0,0), (128,0,0), (0,128,0), (128,128,0),
        (0,0,128), (128,0,128), (0,128,128), (192,192,192)
    ]
    if is_bright:
        cols += [
            (128,128,128), (255,0,0), (0,255,0), (255,255,0),
            (0,0,255), (255,0,255), (0,255,255), (255,255,255)
        ]
    best_i = 0
    best_dist = 1e9
    for i, (cr, cg, cb) in enumerate(cols):
        dist = (r - cr)**2 + (g - cg)**2 + (b - cb)**2
        if dist < best_dist:
            best_dist = dist
            best_i = i
    return best_i

def render_symbols(img, cfg):
    font_ratio = cfg.font_ratio or 0.5

    if cfg.size_w is not None and cfg.size_h is not None:
        cols, rows = cfg.size_w, cfg.size_h
    elif cfg.size_w is not None:
        cols = cfg.size_w
        target_ratio = (img.width / img.height) / font_ratio
        rows = max(1, round(cols / target_ratio))
    elif cfg.size_h is not None:
        rows = cfg.size_h
        target_ratio = (img.width / img.height) / font_ratio
        cols = max(1, round(rows * target_ratio))
    else:
        term_cols = int(os.environ.get("COLUMNS", 80))
        term_rows = int(os.environ.get("LINES", 25))
        max_rows = max(1, term_rows - cfg.margin_bottom)
        max_cols = max(1, term_cols - cfg.margin_right)

        target_ratio = (img.width / img.height) / font_ratio

        if cfg.scale == "max" or cfg.stretch:
            cols = max_cols
            rows = max(1, round(cols / target_ratio))
            if rows > max_rows:
                rows = max_rows
                cols = max(1, round(rows * target_ratio))
        else:
            cols = img.width
            rows = max(1, round(cols / target_ratio))
            if cols > max_cols or rows > max_rows:
                cols = max_cols
                rows = max(1, round(cols / target_ratio))
                if rows > max_rows:
                    rows = max_rows
                    cols = max(1, round(rows * target_ratio))

    if cols <= 0 or rows <= 0:
        cols, rows = 1, 1

    rgba = img.rgba
    iw, ih = img.width, img.height
    color_mode = cfg.colors

    lines = []

    for r in range(rows):
        line_buf = []
        y0 = int(r * ih / rows)
        y1 = max(y0 + 1, int((r + 1) * ih / rows))

        for c in range(cols):
            x0 = int(c * iw / cols)
            x1 = max(x0 + 1, int((c + 1) * iw / cols))

            top_r, top_g, top_b, top_cnt = 0, 0, 0, 0
            bot_r, bot_g, bot_b, bot_cnt = 0, 0, 0, 0

            ymid = (y0 + y1) // 2

            for y in range(y0, y1):
                for x in range(x0, x1):
                    idx = (y * iw + x) * 4
                    pr, pg, pb, pa = rgba[idx], rgba[idx+1], rgba[idx+2], rgba[idx+3]
                    if y < ymid:
                        top_r += pr; top_g += pg; top_b += pb; top_cnt += 1
                    else:
                        bot_r += pr; bot_g += pg; bot_b += pb; bot_cnt += 1

            if top_cnt == 0: top_cnt = 1
            if bot_cnt == 0: bot_cnt = 1

            tr, tg, tb = top_r // top_cnt, top_g // top_cnt, top_b // top_cnt
            br, bg, bb = bot_r // bot_cnt, bot_g // bot_cnt, bot_b // bot_cnt

            if cfg.invert:
                tr, tg, tb, br, bg, bb = br, bg, bb, tr, tg, tb

            if color_mode == "none":
                line_buf.append("@")
            elif color_mode == "full":
                if tr == br and tg == bg and tb == bb:
                    esc = f"\x1b[0m\x1b[7m\x1b[38;2;{tr};{tg};{tb}m \x1b[0m"
                else:
                    esc = f"\x1b[38;2;{tr};{tg};{tb};48;2;{br};{bg};{bb}m▀"
                line_buf.append(esc)
            elif color_mode == "256":
                fg_idx = rgb_to_ansi256(tr, tg, tb)
                bg_idx = rgb_to_ansi256(br, bg, bb)
                if fg_idx == bg_idx:
                    esc = f"\x1b[0m\x1b[7m\x1b[38;5;{fg_idx}m \x1b[0m"
                else:
                    esc = f"\x1b[38;5;{fg_idx};48;5;{bg_idx}m▀"
                line_buf.append(esc)
            elif color_mode == "240":
                fg_idx = rgb_to_ansi256(tr, tg, tb, min_idx=16)
                bg_idx = rgb_to_ansi256(br, bg, bb, min_idx=16)
                if fg_idx == bg_idx:
                    esc = f"\x1b[0m\x1b[7m\x1b[38;5;{fg_idx}m \x1b[0m"
                else:
                    esc = f"\x1b[38;5;{fg_idx};48;5;{bg_idx}m▀"
                line_buf.append(esc)
            elif color_mode == "16":
                fg_idx = rgb_to_ansi16(tr, tg, tb, is_bright=True)
                bg_idx = rgb_to_ansi16(br, bg, bb, is_bright=True)
                fg_code = (30 + fg_idx) if fg_idx < 8 else (90 + (fg_idx - 8))
                bg_code = (40 + bg_idx) if bg_idx < 8 else (100 + (bg_idx - 8))
                if fg_idx == bg_idx:
                    esc = f"\x1b[0m\x1b[7m\x1b[{fg_code}m \x1b[0m"
                else:
                    esc = f"\x1b[{fg_code};{bg_code}m▀"
                line_buf.append(esc)
            elif color_mode == "16/8":
                fg_idx = rgb_to_ansi16(tr, tg, tb, is_bright=True)
                bg_idx = rgb_to_ansi16(br, bg, bb, is_bright=False)
                fg_code = (30 + fg_idx) if fg_idx < 8 else (90 + (fg_idx - 8))
                bg_code = 40 + bg_idx
                esc = f"\x1b[0m\x1b[{fg_code};{bg_code}m \x1b[0m"
                line_buf.append(esc)
            elif color_mode == "8":
                fg_idx = rgb_to_ansi16(tr, tg, tb, is_bright=False)
                bg_idx = rgb_to_ansi16(br, bg, bb, is_bright=False)
                fg_code = 30 + fg_idx
                bg_code = 40 + bg_idx
                if fg_idx == bg_idx:
                    esc = f"\x1b[0m\x1b[7m\x1b[{fg_code}m \x1b[0m"
                else:
                    esc = f"\x1b[{fg_code};{bg_code}m▀"
